sociale positie moeilijk te verenigen. Het verhaal volgt hoe hun verwachtingen over liefde botsen met de maatschappelijke grenzen rondom hen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2031358/een-vorstelijk-aanbod.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789049204068","key":{"isbn_13":"9789049204068"},"before":null,"after":{"work_id":969100059,"title":"Een nobel streven","isbn_13":"9789049204068","isbn_10":"9049204066","language":"nld","publisher":"Meulenhoff Boekerij B.V.","open_library_edition_id":null,"id":969200107}},{"relation":"catalog_edition_metadata","ref":"metadata:9789049204068","key":{"edition_id":"@edition:9789049204068"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-007-20261031","evidence":[{"url":"https://juliaquinn.com/international/romancing-mr-bridgerton-netherlands/","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1547068/een-nobel-streven.html","checkedAt":"2026-10-31T20:24:48.476Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"d91d2026fabd6e216ad143425c675c7541a9f47ff966506dd29cc1e5ea848abe"},{"url":"https://metadata.isbn.nl/ie_fcache/0000630833_Een_nobel_streven_2_710_130_0_0.jpg","checkedAt":"2026-10-31T21:39:11.650Z","http":200,"sha256":"ec19929b54e7a6752aba4d18d38f9c6e2b081e50fd7751fdc51426f712841b64","bytes":151934,"fact":"Decoded and visually inspected31Oct2026 on contact sheets1/2: same verified edition jacket/title/author, readable710px width, original aspect, no crop or arbitrary resize URL. Filename130 is NOT actual pixel height."},{"reviewNote":"No conflicting identity or format evidence found in reviewed exact-edition and content sources."}],"edition_id":"@edition:9789049204068","work_id":969100059,"