stel doet. Hij heeft zich een beeld gevormd van een vrouw die hij nog nauwelijks kent. De ontmoeting confronteert hem met iemand die zelfstandiger en aantrekkelijker is dan verwacht. Hun toenadering vraagt om meer dan een praktische afspraak, terwijl de sociale verwachtingen rond huwelijk en geschiktheid blijven meespelen.","source_type":"official_publisher","source_name":"juliaquinn.com","source_url":"https://juliaquinn.com/international/to-sir-phillip-with-love-6/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022592601","key":{"isbn_13":"9789022592601"},"before":null,"after":{"work_id":969100061,"title":"Een royale vergissing","isbn_13":"9789022592601","isbn_10":"902259260X","language":"nld","publisher":"Meulenhoff Boekerij B.V.","open_library_edition_id":null,"id":969200109}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022592601","key":{"edition_id":"@edition:9789022592601"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-007-20261031","evidence":[{"url":"https://metadata.isbn.nl/1547070/een-royale-vergissing.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1547070/een-royale-vergissing.html","checkedAt":"2026-10-31T20:24:52.776Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"4f811b7758f3c173d9d0dfdba82567f6553024b379fb42fdc7ab21dbb5cd62dc"},{"url":"https://juliaquinn.com/international/when-he-was-wicked-netherlands/","checkedAt":"2026-10-31","fact":"Independent explicit exact-ISBN Dutch-language/translation evidence overriding conflicting Bureau label"},{"url":"https://metadata.isbn.nl/ie_fcache/0000390923_Een_royale_vergissing_0_0.jpg","checkedAt":"2026-10-31T20:31:19.144Z","http":200,"sha256":"ae34235cb69212a9bfd76af451184fc2486607fef754684d2a107ecbb64e0b55","bytes":281834,"