300125,"text":"Feyre jaagt om haar familie door een strenge winter te helpen. Wanneer ze een wolf doodt, blijkt haar daad gevolgen te hebben in een wereld waarvan ze weinig weet. Ze wordt meegenomen naar het rijk Prythian en ontdekt dat haar ontvoerder tot de magische wezens behoort die ze vreest. Op zijn landgoed veranderen haar zekerheden terwijl aantrekkingskracht, onbegrip en dreiging zich steeds moeilijker laten scheiden.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/722475/hof-van-doorns-en-rozen.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789021485850","key":{"isbn_13":"9789021485850"},"before":null,"after":{"work_id":969100064,"title":"Twisted lies","isbn_13":"9789021485850","isbn_10":"9021485850","language":"nld","publisher":"Singel Uitgeverijen","open_library_edition_id":null,"id":969200113}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021485850","key":{"edition_id":"@edition:9789021485850"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-007-20261031","evidence":[{"url":"https://rozet.nl/catalogus/2267732/","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1786929/twisted-lies.html","checkedAt":"2026-10-31T20:32:24.755Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"e4285906a2c380eca29ecf8eda7dc47b6e41d35a9592777f0b525a26cf9130e6"},{"url":"https://metadata.isbn.nl/ie_fcache/0000625709_Twisted_lies_0_0.jpg","checkedAt":"2026-10-31T20:35:07.245Z","http":200,"sha256":"d7e18a7d5eaef03e44c8f3a79f249439d5b353cce836951ed6deecc27ef27bb7","bytes":224659,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote"