 opdracht de god van de dood uit gevangenschap te bevrijden. Hun zoektocht voert hen langs gevaren uit de wereld van de klassieke mythologie. De onderneming maakt deel uit van een grotere strijd waarin zowel Griekse als Romeinse erfenissen doorwerken. Percy moet samenwerken met nieuwe metgezellen terwijl de betekenis van zijn plaats tussen de halfgoden niet vanzelfsprekend is.","source_type":"official_catalog","source_name":"Bibliotheek.nl","source_url":"https://www.bibliotheek.nl/catalogus/titel.429370970.html/de-zoon-van-neptunus/","provenance":"original_source_reviewed_summary"}}],"bindings":[{"work":{"id":969100053,"title":"Time of Contempt","cover_id":null,"author_id":928300131,"work_type":null,"source_type":"open_library","open_library_id":"OL2577481W","first_publish_year":1995,"native_identity_key":null},"author":{"id":928300131,"name":"Andrzej Sapkowski","open_library_id":"OL368638A"}},{"work":{"id":969100054,"title":"Baptism of Fire","cover_id":null,"author_id":928300131,"work_type":null,"source_type":"open_library","open_library_id":"OL2577480W","first_publish_year":1996,"native_identity_key":null},"author":{"id":928300131,"name":"Andrzej Sapkowski","open_library_id":"OL368638A"}},{"work":{"id":969100055,"title":"The Tower of the Swallow","cover_id":null,"author_id":928300131,"work_type":null,"source_type":"open_library","open_library_id":"OL2577478W","first_publish_year":1997,"native_identity_key":null},"author":{"id":928300131,"name":"Andrzej Sapkowski","open_library_id":"OL368638A"}},{"work":{"id":969100056,"title":"Season of Storms","cover_id":null,"author_id":928300131,"work_type":null,"source_type":"open_library","open_library_id":"OL18132591W","first_publish_year":2013,"native_identity_key":null},"author":{"id":928300131,"name":"Andrzej Sapkowski","open_library_id":"OL368638A"}},{"work":{"id":969100057,"title":"The Viscount Who Loved Me","cover_id":null,"author_id":928300429,"work_type":null,"source_type":"open_library","open_library_id":"OL8464993W